Design detail: build the returned object. Let me write:

```js
export function summarize(text, { since } = {}) {
  let sinceMs = null;
  if (since !== undefined && since !== null) {
    sinceMs = typeof since === "number" ? since : Date.parse(since);
    if (Number.isNaN(sinceMs)) {
      throw new TypeError(`invalid --since date: ${JSON.stringify(since)}`);
    }
  }
  const levels = {};
  const times = [];
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const event = JSON.parse(line);
    if (sinceMs !== null) {
      const t = event.time ? Date.parse(event.time) : NaN;
      if (Number.isNaN(t) || t < sinceMs) continue;
    }
    levels[event.level] = (levels[event.level] ?? 0) + 1;
    if (event.time) times.push(event.time);
  }
  times.sort();
  return { levels, first: times[0] ?? null, last: times[times.length - 1] ?? null };
}
```

That's clean. Note: filter active, event included → has valid time so times.push happens.

